scores = [79, 80, 80, 91]
count = 0
for value in scores:
    if value >= 80:
        count = count + 1
    print(count)
strict_count = 0
for value in scores:
    if value > 80:
        strict_count = strict_count + 1
print(strict_count)

def first_index(numbers, target):
    i = 0
    while i < len(numbers):
        if numbers[i] == target:
            return i
        i = i + 1
    return -1

print(first_index([4, 7, 7], 7))

def largest(numbers):
    best = numbers[0]
    i = 1
    while i < len(numbers):
        if numbers[i] > best:
            best = numbers[i]
        i = i + 1
    return best

print(largest([-5]))
print(largest([-8, -3, -6]))

